const uno = part('uno', 'arduino-uno', [-50, -10]);
part('board', 'breadboard', [-18, -10]);
part('remote', 'ir-remote', [52, -10]);
part('bat', 'battery-9v', [16, -34]);
part('motor', 'dc-motor', [13, 16]);

seat('r_led', 'resistor', 'board', '1', 'B8', { value: '220' });
seat('led1', 'led', 'board', 'C', 'D13', { color: 'green' });
seat('d1', 'rectifier-diode', 'board', 'C', 'A26');
seat('q1', 'npn-transistor', 'board', 'E', 'E28');
seat('r_base', 'resistor', 'board', '1', 'B23', { value: '1k' });
seat('ir', 'ir-receiver', 'board', 'GND', 'E42');

wire('w_uno_gnd', uno.pin('GND.1'), 'board:-top2', 'black', [[x(uno.pin('GND.1')), -100], [x('board:-top2'), -100]]);
wire('w_uno_5v', uno.pin('5V'), 'board:+top1', 'red', [[x(uno.pin('5V')), 120], [-195, 120], [-195, y('board:+top1')]]);
wire('w_uno_d13', uno.pin('13'), 'board:A8', 'yellow', [[x(uno.pin('13')), -122], [x('board:A8'), -122]]);
wireV('w_led_gnd', 'board:D13', 'board:-top10', 'black');
wire('w_uno_d5', uno.pin('5'), 'board:A23', 'orange', [[x(uno.pin('5')), -136], [x('board:A23'), -136]]);
wireV('w_q1_gnd', 'board:D28', 'board:-top22', 'black');
wire('w_motor2', 'motor:2', 'board:D30', 'blue', [[x('board:D30'), y('motor:2')]]);
wire('w_motor1', 'motor:1', 'board:D26', 'red', [[x('board:D26'), y('motor:1')]]);
wire('w_bat_neg', 'bat:-', 'board:-top40', 'black', [[x('board:-top40'), y('bat:-')]]);
wire('w_bat_pos', 'bat:+', 'board:B26', 'red', [[325.2, y('bat:+')], [325.2, -103], [x('board:B26'), -103]]);
wireV('w_ir_gnd', 'ir:GND', 'board:-top34', 'black');
wireV('w_ir_vcc', 'ir:VCC', 'board:+top35', 'red');
wire('w_uno_d2', uno.pin('2'), 'ir:DAT', 'purple', [[x(uno.pin('2')), -108], [x('ir:DAT'), -108]]);

